"use client";

import { useState, useRef, useEffect } from "react";
import useVoice from "@/hooks/useVoice";
import { useSpeech } from "@/hooks/useSpeech";

export default function ChatInput({ onSend, loading }) {
  const [text, setText] = useState("");
  const [focused, setFocused] = useState(false);
  const textareaRef = useRef(null);

  const saveHistory = (msg) => {
    try {
      let h = JSON.parse(localStorage.getItem("omnix_chat_history") || "[]");
      h.unshift({ id: Date.now(), title: msg });
      localStorage.setItem("omnix_chat_history", JSON.stringify(h.slice(0, 50)));
    } catch {}
  };

  const { listening, startListening, stopListening } = useVoice((t) => {
    if (!t.trim()) return;
    onSend(`You said: "${t}"`);
  });
  const { stop } = useSpeech();

  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 160) + "px";
  }, [text]);

  const handleSend = () => {
    const t = text.trim();
    if (!t || loading) return;
    stop();
    onSend(t);
    saveHistory(t);
    setText("");
    if (textareaRef.current) textareaRef.current.style.height = "auto";
  };

  const handleStop = () => {
    stop();
    if (typeof window !== "undefined") window.speechSynthesis.cancel();
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleSend(); }
  };

  const handleMic = () => {
    if (listening) { stopListening(); return; }
    stop();
    startListening();
    setTimeout(() => stopListening(), 5000);
  };

  const isEmpty = !text.trim();
  const charCount = text.length;

  return (
    <div className="premium-input-wrap">
      {/* Animated gradient border ring — always rendered, opacity-driven */}
      <div
        className="premium-input-ring"
        style={{ opacity: focused ? 1 : 0, transition: "opacity 0.35s ease" }}
      />

      <div className="premium-input-inner">
        {/* ── Textarea row ── */}
        <div className="flex items-start gap-3 px-4 pt-4">
          {/* Sparkle icon */}
          <div className="mt-[3px] shrink-0">
            <div className="h-6 w-6 rounded-lg gradient-fill flex items-center justify-center text-white select-none"
              style={{ fontSize: 11, fontWeight: 900, boxShadow: "0 2px 12px rgba(124,58,237,0.5)", letterSpacing: "-0.02em" }}>
              ✦
            </div>
          </div>

          <textarea
            ref={textareaRef}
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              if (typeof window !== "undefined") window.speechSynthesis.cancel();
            }}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            onKeyDown={handleKeyDown}
            placeholder={
              loading
                ? "OMNIX is thinking…"
                : listening
                ? "Listening… speak now"
                : "Message OMNIX…  (Shift+Enter for new line)"
            }
            rows={1}
            disabled={loading}
            className="w-full bg-transparent outline-none resize-none leading-relaxed"
            style={{
              color: "var(--t1)",
              fontFamily: "inherit",
              fontSize: 14.5,
              caretColor: "#a78bfa",
              minHeight: 28,
              maxHeight: 160,
            }}
          />
        </div>

        {/* ── Toolbar ── */}
        <div className="flex items-center justify-between px-4 pb-3.5 pt-2 gap-2">

          {/* Left: status hint */}
          <span className="flex items-center gap-1.5 min-w-0" style={{ fontSize: 11, color: "var(--t3)" }}>
            {loading ? (
              <>
                <span className="inline-block h-1.5 w-1.5 rounded-full shrink-0 animate-pulse-ring"
                  style={{ background:"linear-gradient(135deg,#7c3aed,#ec4899)", boxShadow:"0 0 6px rgba(168,85,247,0.8)" }} />
                <span className="truncate">Generating response…</span>
              </>
            ) : listening ? (
              <>
                <span className="inline-block h-1.5 w-1.5 rounded-full shrink-0 animate-pulse-ring"
                  style={{ background:"#22d3ee", boxShadow:"0 0 6px rgba(6,182,212,0.8)" }} />
                <span>Listening…</span>
              </>
            ) : isEmpty ? (
              "Ask anything  ·  Enter to send"
            ) : (
              <>
                <span style={{ color:"#a78bfa", fontWeight:600 }}>{charCount}</span>
                <span> chars  ·  Shift+Enter for new line</span>
              </>
            )}
          </span>

          {/* Right: action buttons */}
          <div className="flex items-center gap-2 shrink-0">

            {/* Mic button */}
            <button
              onClick={handleMic}
              aria-label={listening ? "Stop recording" : "Voice input"}
              className="relative flex h-9 w-9 items-center justify-center rounded-xl transition-all duration-200"
              style={{
                background: listening
                  ? "linear-gradient(135deg, rgba(124,58,237,0.3), rgba(236,72,153,0.22))"
                  : "rgba(99,102,241,0.07)",
                border: `1px solid ${listening ? "rgba(168,85,247,0.5)" : "rgba(99,102,241,0.15)"}`,
                color: listening ? "#c4b5fd" : "var(--t3)",
                boxShadow: listening ? "0 0 20px rgba(168,85,247,0.3), inset 0 1px 0 rgba(255,255,255,0.05)" : "none",
              }}
              onMouseEnter={e => {
                if (!listening) {
                  e.currentTarget.style.background = "rgba(99,102,241,0.14)";
                  e.currentTarget.style.borderColor = "rgba(139,92,246,0.3)";
                  e.currentTarget.style.color = "#a78bfa";
                }
              }}
              onMouseLeave={e => {
                if (!listening) {
                  e.currentTarget.style.background = "rgba(99,102,241,0.07)";
                  e.currentTarget.style.borderColor = "rgba(99,102,241,0.15)";
                  e.currentTarget.style.color = "var(--t3)";
                }
              }}
            >
              {listening && (
                <span className="absolute inset-0 rounded-xl border border-purple-400 opacity-60"
                  style={{ animation:"pulse-ring 1.2s ease-in-out infinite" }} />
              )}
              <svg className="relative z-10 h-4 w-4" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 14a3 3 0 003-3V7a3 3 0 10-6 0v4a3 3 0 003 3zm5-3a1 1 0 10-2 0 3 3 0 11-6 0 1 1 0 10-2 0 5 5 0 0010 0zm-5 9a1 1 0 001-1v-3h-2v3a1 1 0 001 1z" />
              </svg>
            </button>

            {/* Stop button — shown only while generating */}
            {loading && (
              <button
                onClick={handleStop}
                aria-label="Stop generating"
                className="flex h-9 items-center gap-2 rounded-xl px-4 text-[12.5px] font-bold tracking-wide transition-all duration-200"
                style={{
                  background: "rgba(248,113,113,0.1)",
                  border: "1px solid rgba(248,113,113,0.3)",
                  color: "#f87171",
                  boxShadow: "0 0 16px rgba(248,113,113,0.15)",
                }}
                onMouseEnter={e => { e.currentTarget.style.background = "rgba(248,113,113,0.18)"; e.currentTarget.style.boxShadow = "0 0 24px rgba(248,113,113,0.25)"; }}
                onMouseLeave={e => { e.currentTarget.style.background = "rgba(248,113,113,0.1)"; e.currentTarget.style.boxShadow = "0 0 16px rgba(248,113,113,0.15)"; }}
              >
                <svg className="h-3.5 w-3.5" fill="currentColor" viewBox="0 0 24 24">
                  <rect x="4" y="4" width="16" height="16" rx="2" />
                </svg>
                Stop
              </button>
            )}

            {/* Send button */}
            {!loading && (
              <button
                onClick={handleSend}
                disabled={isEmpty}
                aria-label="Send message"
                className="premium-send-btn flex h-9 items-center gap-2 rounded-xl px-5 text-[13px] font-bold tracking-wide text-white"
                style={{
                  opacity: isEmpty ? 0.45 : 1,
                  cursor: isEmpty ? "not-allowed" : "pointer",
                }}
              >
                Send
                <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                </svg>
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
