"use client";

import { useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import BrainLogo from "@/components/ui/BrainLogo";

/* ── Language color map for code blocks ───────────────────── */
const LANG_COLORS = {
  javascript:"#f7df1e", js:"#f7df1e",
  typescript:"#3178c6", ts:"#3178c6",
  python:"#3776ab",     py:"#3776ab",
  css:"#1572b6",        html:"#e34f26",
  json:"#8bc34a",       bash:"#4eaa25",
  shell:"#4eaa25",      sh:"#4eaa25",
  sql:"#f29111",        rust:"#ce422b",
  go:"#00add8",         java:"#ed8b00",
  c:"#a8b9cc",          cpp:"#00599c",
  ruby:"#cc342d",       swift:"#f05138",
  kotlin:"#7f52ff",     php:"#777bb4",
  yaml:"#cb171e",       toml:"#9c4121",
  dockerfile:"#0db7ed", graphql:"#e10098",
};

/* ── Copy button ──────────────────────────────────────────── */
function CopyBtn({ text, label = "Copy", size = "sm" }) {
  const [copied, setCopied] = useState(false);
  const go = () => {
    navigator.clipboard.writeText(text).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };
  return (
    <button
      onClick={go}
      className="flex items-center gap-1 rounded-md transition-all duration-200 font-semibold"
      style={{
        padding: size === "sm" ? "3px 8px" : "4px 12px",
        fontSize: size === "sm" ? 10.5 : 11.5,
        background: copied ? "rgba(34,197,94,0.12)" : "rgba(99,102,241,0.09)",
        border: `1px solid ${copied ? "rgba(34,197,94,0.35)" : "rgba(139,92,246,0.22)"}`,
        color: copied ? "#4ade80" : "#a78bfa",
        letterSpacing: "0.02em",
      }}
      onMouseEnter={e => { if (!copied) { e.currentTarget.style.background = "rgba(99,102,241,0.16)"; e.currentTarget.style.borderColor = "rgba(139,92,246,0.38)"; } }}
      onMouseLeave={e => { if (!copied) { e.currentTarget.style.background = "rgba(99,102,241,0.09)"; e.currentTarget.style.borderColor = "rgba(139,92,246,0.22)"; } }}
    >
      {copied ? (
        <><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5"/></svg> Copied</>
      ) : (
        <><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15.666 3.888A2.25 2.25 0 0013.5 2.25h-3c-1.03 0-1.9.693-2.166 1.638m7.332 0c.055.194.084.4.084.612v0a.75.75 0 01-.75.75H9a.75.75 0 01-.75-.75v0c0-.212.03-.418.084-.612m7.332 0c.646.049 1.288.11 1.927.184 1.1.128 1.907 1.077 1.907 2.185V19.5a2.25 2.25 0 01-2.25 2.25H6.75A2.25 2.25 0 014.5 19.5V6.257c0-1.108.806-2.057 1.907-2.185a48.208 48.208 0 011.927-.184"/></svg> {label}</>
      )}
    </button>
  );
}

/* ── Premium Code Block ───────────────────────────────────── */
function CodeBlock({ children, className }) {
  const lang = className?.replace("language-", "") || "code";
  const color = LANG_COLORS[lang.toLowerCase()] || "#a78bfa";
  const code = String(children).replace(/\n$/, "");
  return (
    <div className="code-block my-4">
      {/* Header: Mac traffic lights + language badge + copy */}
      <div className="code-block-header">
        <div className="flex items-center gap-1.5">
          <span style={{ display:"block", width:11, height:11, borderRadius:"50%", background:"#ff5f57", flexShrink:0 }} />
          <span style={{ display:"block", width:11, height:11, borderRadius:"50%", background:"#febc2e", flexShrink:0 }} />
          <span style={{ display:"block", width:11, height:11, borderRadius:"50%", background:"#28c840", flexShrink:0 }} />
        </div>
        <span className="flex items-center gap-1.5 font-bold tracking-wider" style={{ fontSize:10, color, letterSpacing:"0.1em" }}>
          <span style={{ width:6, height:6, borderRadius:"50%", background:color, boxShadow:`0 0 6px ${color}88`, display:"block", flexShrink:0 }} />
          {lang.toUpperCase()}
        </span>
        <CopyBtn text={code} label="Copy" size="sm" />
      </div>
      {/* Code area */}
      <div className="overflow-x-auto">
        <pre style={{ margin:0, padding:"18px 22px", color:"#ddd6fe", fontSize:13, lineHeight:1.85, fontFamily:"var(--font-geist-mono,'Fira Code',monospace)" }}>
          <code>{code}</code>
        </pre>
      </div>
    </div>
  );
}

/* ── Small reaction/action buttons ───────────────────────── */
function ActionBtn({ icon, label, onClick, active, activeColor = "#22d3ee" }) {
  const [hov, setHov] = useState(false);
  return (
    <button
      onClick={onClick}
      title={label}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      className="flex items-center justify-center rounded-lg transition-all duration-200"
      style={{
        padding: "4px 7px",
        color: active ? activeColor : hov ? "#c4b5fd" : "var(--t3)",
        background: active ? `${activeColor}18` : hov ? "rgba(139,92,246,0.1)" : "transparent",
        border: `1px solid ${active ? `${activeColor}35` : hov ? "rgba(139,92,246,0.2)" : "transparent"}`,
      }}
    >
      {icon}
    </button>
  );
}

const IcoThumbUp = () => (
  <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M14 10h4.764a2 2 0 011.789 2.894l-3.5 7A2 2 0 0115.263 21h-4.017c-.163 0-.326-.02-.485-.06L7 20m7-10V5a2 2 0 00-2-2h-.095c-.5 0-.905.405-.905.905 0 .714-.211 1.412-.608 2.006L7 11v9m7-10h-2M7 20H5a2 2 0 01-2-2v-6a2 2 0 012-2h2.5" />
  </svg>
);
const IcoThumbDown = () => (
  <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M10 14H5.236a2 2 0 01-1.789-2.894l3.5-7A2 2 0 018.736 3h4.018c.163 0 .326.02.485.06L17 4m-7 10v2a2 2 0 002 2h.095c.5 0 .905-.405.905-.904 0-.715.211-1.413.608-2.008L17 13V4m-7 10h2m5-10h2a2 2 0 012 2v6a2 2 0 01-2 2h-2.5" />
  </svg>
);
const IcoRegen = () => (
  <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99" />
  </svg>
);

/* ── Main message component ───────────────────────────────── */
export default function ChatMessage({ message }) {
  const isUser = message.role === "user";
  const [liked, setLiked]       = useState(false);
  const [disliked, setDisliked] = useState(false);

  const now = new Date();
  const ts  = message.timestamp
    ? new Date(message.timestamp)
    : now;
  const timeStr = ts.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

  return (
    <div className={`w-full flex animate-chat-enter mb-1 ${isUser ? "justify-end" : "justify-start"}`}>
      <div className={`flex items-start gap-3 max-w-[90%] sm:max-w-[82%] ${isUser ? "flex-row-reverse" : ""}`}>

        {/* ── Avatar ── */}
        {isUser ? (
          <div className="shrink-0 mt-0.5">
            <div className="relative h-8 w-8">
              {/* Glow ring */}
              <div className="absolute -inset-[3px] rounded-[14px] opacity-60"
                style={{ background:"linear-gradient(135deg,#7c3aed,#ec4899,#06b6d4)", filter:"blur(4px)" }} />
              <div className="relative h-8 w-8 rounded-xl gradient-fill flex items-center justify-center text-[11px] font-black text-white"
                style={{ boxShadow:"0 4px 20px rgba(124,58,237,0.55)" }}>U</div>
            </div>
          </div>
        ) : (
          <div className="shrink-0 mt-0.5">
            <div className="relative h-8 w-8">
              {/* Soft pulsing ring */}
              <div className="absolute -inset-[3px] rounded-[14px] opacity-0 group-hover:opacity-40 animate-pulse-ring"
                style={{ background:"linear-gradient(135deg,#7c3aed,#a855f7,#06b6d4)", filter:"blur(5px)" }} />
              <div className="relative h-8 w-8 rounded-xl flex items-center justify-center overflow-hidden"
                style={{ background:"rgba(11,4,28,0.97)", border:"1px solid rgba(124,58,237,0.32)", boxShadow:"0 4px 22px rgba(109,40,217,0.32)" }}>
                <div className="absolute inset-0" style={{ background:"radial-gradient(circle at 40% 35%, rgba(168,85,247,0.35), transparent 65%)" }} />
                <BrainLogo size={26} animate={false} />
              </div>
            </div>
          </div>
        )}

        {/* ── Bubble + meta ── */}
        <div className="group relative min-w-0 flex-1">

          {/* Label + timestamp */}
          <div className={`flex items-center gap-2 mb-1.5 ${isUser ? "justify-end" : "justify-start"}`}>
            <span className="text-[11px] font-bold tracking-[0.12em] uppercase"
              style={{ color: isUser ? "rgba(167,139,250,0.65)" : "rgba(192,132,252,0.55)" }}>
              {isUser ? "You" : "OMNIX"}
            </span>
            <span className="text-[10px] opacity-0 group-hover:opacity-100 transition-opacity duration-300 select-none"
              style={{ color:"var(--t3)" }}>
              {timeStr}
            </span>
          </div>

          {/* ── User bubble ── */}
          {isUser ? (
            <div className="relative bubble-user rounded-2xl rounded-tr-sm px-4 py-3.5 text-[14.5px] leading-relaxed text-white">
              {/* Inner glass highlight top-right corner */}
              <div className="absolute top-0 right-0 w-28 h-14 rounded-tr-2xl pointer-events-none"
                style={{ background:"linear-gradient(135deg, rgba(255,255,255,0.13) 0%, transparent 65%)" }} />
              {/* Subtle inner glow at bottom */}
              <div className="absolute bottom-0 left-4 right-4 h-px rounded-full pointer-events-none"
                style={{ background:"linear-gradient(90deg,transparent,rgba(255,255,255,0.15),transparent)" }} />
              <p style={{ whiteSpace:"pre-wrap", wordBreak:"break-word", position:"relative", zIndex:1 }}>{message.content}</p>
            </div>

          /* ── AI bubble ── */
          ) : (
            <div className="relative bubble-ai rounded-2xl rounded-tl-sm px-4 py-3.5 text-[14.5px] leading-relaxed"
              style={{ color:"var(--t1)" }}>
              {/* Top gradient shimmer */}
              <div className="absolute top-0 left-6 right-6 h-px rounded-full opacity-50"
                style={{ background:"linear-gradient(90deg,transparent,rgba(167,139,250,0.8),rgba(232,121,249,0.6),transparent)" }} />
              {/* Left accent line */}
              <div className="absolute left-0 top-3 bottom-3 w-[2px] rounded-full"
                style={{ background:"linear-gradient(180deg,rgba(124,58,237,0.7),rgba(217,70,239,0.45),rgba(6,182,212,0.2))" }} />
              {/* Corner detail */}
              <div className="absolute top-0 left-0 w-16 h-10 rounded-tl-2xl pointer-events-none"
                style={{ background:"linear-gradient(135deg,rgba(124,58,237,0.08),transparent)" }} />

              <div className="prose-omnix" style={{ wordBreak:"break-word" }}>
                <ReactMarkdown
                  remarkPlugins={[remarkGfm]}
                  components={{
                    p:          ({ children }) => <div className="mb-[0.65em] last:mb-0">{children}</div>,
                    ul:         ({ children }) => <ul>{children}</ul>,
                    ol:         ({ children }) => <ol>{children}</ol>,
                    li:         ({ children }) => <li>{children}</li>,
                    strong:     ({ children }) => <strong>{children}</strong>,
                    em:         ({ children }) => <em>{children}</em>,
                    blockquote: ({ children }) => <blockquote>{children}</blockquote>,
                    h1:         ({ children }) => <h1>{children}</h1>,
                    h2:         ({ children }) => <h2>{children}</h2>,
                    h3:         ({ children }) => <h3>{children}</h3>,
                    a:          ({ href, children }) => <a href={href} target="_blank" rel="noopener noreferrer">{children}</a>,
                    table:      ({ children }) => <div className="overflow-x-auto my-3"><table>{children}</table></div>,
                    th:         ({ children }) => <th>{children}</th>,
                    td:         ({ children }) => <td>{children}</td>,
                    code({ inline, className, children }) {
                      return inline
                        ? (
                          <code style={{
                            background:"rgba(99,102,241,0.16)",
                            color:"#c4b5fd",
                            border:"1px solid rgba(139,92,246,0.25)",
                            borderRadius:6,
                            padding:"2px 7px",
                            fontSize:"0.87em",
                            fontFamily:"var(--font-geist-mono,'Fira Code',monospace)",
                          }}>{children}</code>
                        )
                        : <CodeBlock className={className}>{children}</CodeBlock>;
                    },
                  }}
                >
                  {message.content}
                </ReactMarkdown>
              </div>
            </div>
          )}

          {/* ── AI action row ── */}
          {!isUser && (
            <div className="mt-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300">
              <CopyBtn text={message.content} label="Copy response" size="sm" />
              <ActionBtn
                icon={<IcoThumbUp />}
                label="Helpful"
                onClick={() => { setLiked(v => !v); setDisliked(false); }}
                active={liked}
                activeColor="#22d3ee"
              />
              <ActionBtn
                icon={<IcoThumbDown />}
                label="Not helpful"
                onClick={() => { setDisliked(v => !v); setLiked(false); }}
                active={disliked}
                activeColor="#f87171"
              />
              <ActionBtn
                icon={<IcoRegen />}
                label="Regenerate"
                onClick={() => {}}
                activeColor="#a78bfa"
              />
            </div>
          )}

          {/* ── User: subtle copy on hover ── */}
          {isUser && (
            <div className="mt-1.5 flex justify-end opacity-0 group-hover:opacity-100 transition-all duration-300">
              <CopyBtn text={message.content} label="Copy" size="sm" />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
